-- =============================================
-- Author:		Monir
-- Create date: 7-5-2024
-- Description:	A procedure to extract the center number of children active days within the predefine ranges
-- =============================================
CREATE PROCEDURE [dbo].[iCareAdmin_getCenterChildrenMonthlyActiveDaysStats]
    @centerID		INT,
    @requestMonth	INT,
    @requestYear	INT,
    @lessThan5		INT OUTPUT,
    @between5And13	INT OUTPUT,
    @above13		INT OUTPUT
AS
BEGIN
    DECLARE @toDate DATE;
	DECLARE @startOfMonth DATE;
    DECLARE @today DATE = GETUTCDATE();

    -- Temporary table to store the children details
    CREATE TABLE #Children (child_id INT,is_Demo BIT,child_name NVARCHAR(MAX));

    -- Insert the results from the stored procedure into the temporary table
    INSERT INTO #Children (child_id, is_Demo, child_name)
	    EXEC [dbo].[iCareAdmin_getCenterClassChildren]
			@classID = -1,
			@requestAll = 1,
			@centerID = @centerID,
			@requestYear = @requestYear,
			@requestMonth = @requestMonth;

     -- Logic to set startOfMonth and toDate
    SET @startOfMonth = CONVERT(DATE, CONCAT(@requestYear, '[SQL literal withheld]', RIGHT('[SQL literal withheld]' + CAST(@requestMonth AS VARCHAR(2)), 2), '[SQL literal withheld]'));
    SET @toDate = DATEADD(DAY, -1, DATEADD(MONTH, 1, @startOfMonth));

    IF @toDate > @today
    BEGIN
        SET @toDate = @today;
    END

    -- Temporary table to store the active days result
    CREATE TABLE #ActiveDays (child_id INT,active_days INT);

    -- Variable to store the active days
    DECLARE @childID INT, @activeDays INT;
    
    -- Cursor to loop through all non-demo children
    DECLARE children_cursor CURSOR FOR
    SELECT child_id FROM #Children WHERE is_Demo = 0;

    OPEN children_cursor;
    FETCH NEXT FROM children_cursor INTO @childID;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        -- Call the stored procedure to get active days for each child
        EXEC @activeDays = dbo.[iCareAdmin_getChildActiveDays] 
            @toDate = @toDate,
			@childID = @childID,
			@yearRequested  = @requestYear,
			@startOfMonth   = @startOfMonth,
            @monthRequested = @requestMonth;

        -- Insert the result into the #ActiveDays table
        INSERT INTO #ActiveDays (child_id, active_days)
        VALUES (@childID, @activeDays);

        FETCH NEXT FROM children_cursor INTO @childID;
    END;

    CLOSE children_cursor;
    DEALLOCATE children_cursor;

    -- Select and assign the number of children with active days between 1 and 5
    SELECT @lessThan5 = COUNT(*) FROM #ActiveDays WHERE active_days BETWEEN 1 AND 5;

    -- Select and assign the number of children with active days between 6 and 13
    SELECT @between5And13 = COUNT(*) FROM #ActiveDays WHERE active_days BETWEEN 6 AND 13;

    -- Select and assign the number of children with active days > 13
    SELECT @above13 = COUNT(*) FROM #ActiveDays WHERE active_days > 13;

    -- Drop the temporary tables
    DROP TABLE #Children;
    DROP TABLE #ActiveDays;
END

-- =============================================
-- Author:		Monir
-- Create date: 7-5-2024
-- Description:	A procedure to fetch and calculate a child number of active days within a month
-- =============================================

CREATE PROCEDURE [dbo].[iCareAdmin_getChildActiveDays]
    @childID INT,
    @monthRequested INT,
    @yearRequested INT,
    @startOfMonth DATE,
    @toDate DATE
AS
BEGIN
    -- Define enum values as variables
    DECLARE @TransactionTypeAdd INT = 1;
    DECLARE @TransactionTypeActivate INT = 2;
    DECLARE @TransactionTypeDeactivate INT = 3;
    DECLARE @TransactionTypeDelete INT = 5;

    -- Create a temporary table to store results from the child activation transactions
    CREATE TABLE #ptable (
        child_id INT,
        transaction_code INT,
        transaction_date DATETIME,
        trans_date DATETIME,
        this_month INT
    );

    -- Insert the results from the stored procedure into the temporary table
    INSERT INTO #ptable
    EXEC [dbo].[iCareAdmin_getChildLatestActivationTransactions] @childID, @monthRequested, @yearRequested;

    -- Initialize variables
    DECLARE @activeDays INT = 0;
    DECLARE @mDate DATETIME;

    -- Handle case when there are no transactions
    IF (SELECT COUNT(*) FROM #ptable) = 0
    BEGIN
        -- If no transactions, the child is active for all days of the current month
        SET @activeDays = DATEDIFF(DAY, @startOfMonth, @toDate);
    END
    -- Handle case when there is only one transaction
    ELSE IF (SELECT COUNT(*) FROM #ptable) = 1
    BEGIN
        DECLARE @this_month INT = (SELECT this_month FROM #ptable);
        DECLARE @transaction_code INT = (SELECT transaction_code FROM #ptable);

        IF @this_month = 0
        BEGIN
            -- If the transaction is not from this month, check the transaction code
            IF @transaction_code IN (@TransactionTypeAdd, @TransactionTypeActivate)
            BEGIN
                SET @activeDays = DATEDIFF(DAY, @startOfMonth, @toDate);
            END
            ELSE IF @transaction_code IN (@TransactionTypeDeactivate, @TransactionTypeDelete)
            BEGIN
                SET @activeDays = 0;
            END
        END
        ELSE
        BEGIN
            SET @mDate = (SELECT trans_date FROM #ptable);
            IF @transaction_code IN (@TransactionTypeAdd, @TransactionTypeActivate)
            BEGIN
                SET @activeDays = DATEDIFF(DAY, @mDate, @toDate);
            END
            ELSE IF @transaction_code IN (@TransactionTypeDeactivate, @TransactionTypeDelete)
            BEGIN
                SET @activeDays = DATEDIFF(DAY, @startOfMonth, @mDate);
            END
        END
    END
    -- Handle case when there are multiple transactions
    ELSE
    BEGIN
        DECLARE @initiallyActive BIT;
        DECLARE @first_transaction_code INT = (SELECT TOP 1 transaction_code FROM #ptable ORDER BY trans_date);
        DECLARE @first_this_month INT = (SELECT TOP 1 this_month FROM #ptable ORDER BY trans_date);

        -- Determine initial activity state
        IF @first_this_month = 0
        BEGIN
            SET @initiallyActive = CASE 
                                    WHEN @first_transaction_code IN (@TransactionTypeAdd, @TransactionTypeActivate) THEN 1
                                    ELSE 0
                                   END;
            DELETE FROM #ptable WHERE this_month = 0 AND transaction_code = @first_transaction_code;
        END
        ELSE
        BEGIN
            SET @initiallyActive = CASE WHEN @first_transaction_code IN (@TransactionTypeAdd, @TransactionTypeActivate) THEN 0 ELSE 1 END;
        END

        -- If initially active, calculate days from the start of the month to the first transaction
        IF @initiallyActive = 1
        BEGIN
            SET @mDate = (SELECT TOP 1 trans_date FROM #ptable ORDER BY trans_date);
            SET @activeDays = DATEDIFF(DAY, @startOfMonth, @mDate);
        END

        -- Loop through the rest of the transactions to calculate active periods
        DECLARE @i INT = 1;
        DECLARE @current_transaction_code INT;
        DECLARE @current_trans_date DATETIME;
        DECLARE @next_trans_date DATETIME;

        WHILE @i <= (SELECT COUNT(*) FROM #ptable)
        BEGIN
            SET @current_transaction_code = (SELECT transaction_code FROM #ptable ORDER BY trans_date OFFSET @i - 1 ROWS FETCH NEXT 1 ROWS ONLY);
            SET @current_trans_date = (SELECT trans_date FROM #ptable ORDER BY trans_date OFFSET @i - 1 ROWS FETCH NEXT 1 ROWS ONLY);

            -- Skip deactivation and deletion transactions for active day calculation
            IF @current_transaction_code NOT IN (@TransactionTypeDeactivate, @TransactionTypeDelete)
            BEGIN
                IF @i = (SELECT COUNT(*) FROM #ptable)
                BEGIN
                    SET @activeDays = @activeDays + DATEDIFF(DAY, @current_trans_date, @toDate);
                END
                ELSE
                BEGIN
                    SET @next_trans_date = (SELECT trans_date FROM #ptable ORDER BY trans_date OFFSET @i ROWS FETCH NEXT 1 ROWS ONLY);
                    SET @activeDays = @activeDays + DATEDIFF(DAY, @current_trans_date, @next_trans_date);
                END
            END

            SET @i = @i + 1;
        END
    END

    -- Drop the temporary table
    DROP TABLE #ptable;

	RETURN @activeDays
END
